import {titles,icons,seedCompanies,messages,campaigns,creativeNames,workItems,phaseNames} from './demo.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm4 5-2 6-6 2 2-6 6-2z',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16zm6 14 4 4',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3zm-4 9 3 3 5-6',building:'M4 21V3h12v18M16 10h4v11M8 7h4M8 11h4M8 15h4M2 21h20',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm-7 18v-3a6 6 0 0 1 12 0v3M17 4a4 4 0 0 1 0 8m1 3a5 5 0 0 1 4 5v1',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3z',edit:'m16 3 5 5-12 12-6 1 1-6L16 3zm-3 3 5 5',image:'M3 3h18v18H3zM3 16l6-6 6 7 3-3 3 3M15 7h.01',video:'M3 5h12v14H3zM15 9l6-4v14l-6-4',folder:'M3 6h7l2 3h9v12H3V6z',send:'m3 3 19 9-19 9 4-9-4-9zm4 9h15',inbox:'M6 3h12l4 11v7H2v-7L6 3zm-4 11h6l2 3h4l2-3h6',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm0 4h.01',connect:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 12h10m-4-4 4 4-4 4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm0-5v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m4 12 5 5L20 6',close:'m5 5 14 14M19 5 5 19',menu:'M3 6h18M3 12h18M3 18h18',plus:'M12 4v16M4 12h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm0 4v6l4 2',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',bell:'M6 16V9a6 6 0 0 1 12 0v7l2 2H4l2-2zm4 5h4',book:'M3 3h7l2 2 2-2h7v17h-7l-2 1-2-1H3V3zm9 2v16',pause:'M8 4v16M16 4v16'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const pill=(v,c)=>`<span class="pill ${c||({Verified:'green',Qualified:'green',Accepted:'green',Approved:'green','Opted in':'green',Ready:'blue','Needs review':'orange','Needs approval':'orange',Draft:'purple',Suppressed:'red',Failed:'red',Irrelevant:'red','Opted out':'red'}[v]||'')}">${esc(v)}</span>`;
const btn=(label,action,kind='',ico)=>`<button class="btn ${kind}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const link=(label,to,kind='',ico)=>`<a class="btn ${kind}" href="#/${to}">${ico?icon(ico):''}${label}</a>`;
const money=n=>'৳'+n.toLocaleString('en-US');
let modules=[],route=[],timer,importRows=null;
const initial=()=>({companies:structuredClone(seedCompanies),flows:{},forms:{},approved:[false,false,false],campaigns:structuredClone(campaigns),qualified:[],transfers:[],selectedMessage:0,paused:false,settings:{mask:true,review:true,consent:true},audit:[],drafts:{},imported:false});
let state=initial();try{const saved=JSON.parse(sessionStorage.getItem('gm-print:v2:public-demo:2026'));if(saved&&saved.companies&&saved.flows)state={...state,...saved};}catch{}
function save(){try{sessionStorage.setItem('gm-print:v2:public-demo:2026',JSON.stringify(state));}catch{toast('Browser storage unavailable. Changes stay in this session.');}}
function log(action){state.audit.unshift({action,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});state.audit=state.audit.slice(0,30);save();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function head(title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow" style="margin-bottom:8px">GM Print workspace</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function panel(title,body,extra='',sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>${body}</section>`;}
function stat(label,value,note,ico){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;}
function currentModule(){return modules.find(m=>m.id===route[1]);}
function nav(){let out=`<a class="nav-item ${route[0]==='overview'?'active':''}" href="#/overview">${icon('grid')}Overview</a>`;const groups={0:'Foundation',6:'Create with AI',10:'Activate & convert',14:'Connect & govern'};modules.forEach((m,i)=>{if(groups[i])out+=`<div class="nav-label">${groups[i]}</div>`;out+=`<a class="nav-item ${route[1]===m.id?'active':''}" href="#/module/${m.id}">${icon(icons[i])}<span>${titles[i]}</span><span class="nav-num">${String(i+1).padStart(2,'0')}</span></a>`;});return out+`<div class="nav-label">Blueprint</div><a class="nav-item ${route[0]==='coverage'?'active':''}" href="#/coverage">${icon('book')}Module explorer <span class="nav-num">64</span></a>`;}
function render(){route=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(!route.length)route=['overview'];let m=currentModule();const known=route[0]==='overview'||route[0]==='coverage'||(route[0]==='module'&&m);document.title=`${m?titles[modules.indexOf(m)]:route[0]==='coverage'?'Module explorer':'Overview'} · GM Print Studio v2`;
$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#/overview"><span class="brand-mark">gm</span><span><strong>GM Print</strong><small>MARKETING STUDIO</small></span></a><div class="workspace"><span class="avatar">GM</span><div><strong>GM Print Solution</strong><small style="display:block;margin-top:3px">Demo workspace</small></div></div><nav class="nav-scroll" aria-label="Main navigation">${nav()}</nav><div class="side-foot"><span class="avatar" style="background:#efe8dd;color:#8c744e">MR</span><div><strong>Marketing team</strong><small>Workspace administrator · demo</small></div></div></aside><button class="mobile-overlay" data-action="menu" aria-label="Close navigation"></button><div class="body"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">Workspace ${icon('chevron')} <span>${m?titles[modules.indexOf(m)]:route[0]==='coverage'?'Module explorer':'Overview'}</span></div><div class="top-right"><button class="search-btn" data-action="search" aria-label="Search workspace">${icon('search')}<span class="search-text">Search workspace</span><span class="kbd">⌘ K</span></button><span class="demo-label">V2 DEVELOPMENT DEMO</span><button class="icon-btn" data-action="notifications" aria-label="View notifications">${icon('bell')}</button><span class="avatar" style="background:#efe8dd;color:#8c744e">MR</span></div></header><div class="demo-ribbon">কাল্পনিক ডেটা · পরিবর্তন এই browser session-এ থাকে · কোনো live message, বিজ্ঞাপন বা ERP call হয় না</div><main id="main" class="content" tabindex="-1">${known?(m?modulePage(m):route[0]==='coverage'?coverage():overview()):head('Page not found','এই লিংকের মডিউলটি পাওয়া যায়নি।',link('Open workspace','overview','primary'))}<div class="footer-note"><span>GM Print Solution · Marketing Studio</span><span>v2 development · v1 baseline · ${modules.length} modules / 64 submodules / 192 phases · <button class="link" data-action="reset">Reset demo</button></span></div></main></div></div>`;
bind();}
function companyTable(items=state.companies.slice(0,4)){return `<div class="table-wrap"><table><thead><tr><th>COMPANY</th><th>INDUSTRY / LOCATION</th><th>CHANNELS</th><th>STATUS</th><th></th></tr></thead><tbody>${items.map(c=>`<tr class="row-link"><td><div class="company-name"><span class="company-logo">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.id)} · ${esc(c.contact)}</small></div></div></td><td>${esc(c.industry)}<small>${esc(c.location)}</small></td><td>${c.channels.map(v=>`<span class="channel-tag">${esc(v)}</span>`).join('')}</td><td>${pill(c.status)}</td><td><button class="icon-btn" data-company="${c.id}" aria-label="View ${esc(c.name)}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">কোনো কোম্পানি পাওয়া যায়নি। ফিল্টার পরিবর্তন করুন।</td></tr>'}</tbody></table></div>`;}
function overview(){return head('Your marketing, connected.','কোম্পানি খোঁজা থেকে যোগ্য লিড—সব কাজ এক জায়গায়।',link('Import contacts','module/M02','', 'upload')+link('Create content','module/M08/S1','primary','plus'))+`<div class="stats">${stat('Company profiles',state.companies.length,'<span class="trend">4 verified</span> fictional company records','building')}${stat('Content in review',3-state.approved.filter(Boolean).length,'<span class="trend">3 creatives</span> ready for your review','image')}${stat('Qualified leads',state.qualified.length,'<span class="trend">3 inquiries</span> in the response inbox','target')}${stat('ERP handoffs',state.transfers.filter(t=>t.status==='Accepted').length,'<span class="trend">Demo sandbox</span> sales continue in ERP','connect')}</div><div class="grid-2">${panel('From discovery to opportunity',`<div class="journey">${[['building','Companies',state.companies.length,'M05'],['users','Segments',4,'M06'],['spark','Content',3,'M11'],['send','Campaigns',state.campaigns.length,'M12'],['target','Qualified',state.qualified.length,'M14']].map(([i,l,n,m])=>`<a class="journey-step" href="#/module/${m}">${icon(i)}<b>${n}</b><span>${l}</span></a>`).join('')}</div><div class="journey-foot">${icon('connect')} Qualified leads move to your existing ERP. Sales & KPI stay there.</div>`,pill('Live demo','green'),'Your complete marketing journey')}${panel('Needs your attention',`<div class="panel-body">${[['image','orange',(3-state.approved.filter(Boolean).length)+' creative drafts','Review copy, claims and brand','module/M11'],['shield','blue','1 contact needs review','Resolve source and role mismatch','module/M04/S3'],['inbox','green','3 new conversations','Classify intent and qualify leads','module/M13']].map(([i,c,t,s,r])=>`<a class="review-row" href="#/${r}"><span class="tile-icon ${c}">${icon(i)}</span><span class="grow"><strong>${t}</strong><small>${s}</small></span>${icon('chevron')}</a>`).join('')}</div>`,pill('Action queue'))}</div><div class="grid-2">${panel('Campaign pulse',`<div class="panel-body"><div class="flex-between"><div><span class="eyebrow">Illustrative response activity</span><div style="font-size:25px;font-weight:700;margin-top:5px">Meaningful conversations</div></div><span class="pill green">Demo week</span></div><div class="chart" role="img" aria-label="Illustrative weekly activity chart, sample responses versus inquiries">${[34,55,42,78,66,94,84].map((v,i)=>`<div class="chart-col"><div class="bar" style="--h:${v}%"></div><div class="bar light" style="--h:${[18,25,20,45,38,60,50][i]}%"></div></div>`).join('')}</div><div class="chart-labels">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="legend"><span><i></i>Responses</span><span><i class="light"></i>Product inquiries</span><span>Illustrative sample · not live reporting</span></div></div>`,link('View campaigns','module/M12','small'))}${panel('A clear next step',`<div class="panel-body"><span class="pill green">Recommended demo journey</span><h2 style="font-size:23px;margin:18px 0 10px">Turn a sample request<br>into a qualified lead.</h2><p class="muted" style="font-size:14px">Meghna Apparel Studio wants 10,000 recycled hangtags. Review the conversation, extract the requirement and send it to the ERP demo.</p><div class="actions" style="margin-top:24px">${link('Open response inbox','module/M13','primary','arrow')}</div><div class="detail-row" style="margin-top:15px"><span>Source</span><b>WhatsApp · demo opt-in</b></div><div class="detail-row"><span>Request</span><b>Sample + catalogue</b></div></div>`)}</div>${panel('Your company network',companyTable(),link('View all companies','module/M05','small'),'Verified profiles and conversations, connected')}<div class="section-title"><h2>Explore your workspace</h2>${link('All 64 submodules','coverage','ghost small','arrow')}</div><div class="module-grid">${modules.slice(0,8).map(moduleCard).join('')}</div>`;}
function moduleCard(m){const i=modules.indexOf(m);return `<a class="module-card" href="#/module/${m.id}"><div class="top"><span class="tile-icon green">${icon(icons[i])}</span><span class="code">${m.id}</span></div><h3>${titles[i]}</h3><p class="bn">${m.title}</p><div class="progress-track"><span style="--w:100%"></span></div><small>4 submodules · 12 workflow phases</small></a>`;}
function coverage(){return head('Every module. Every workflow.','ডকুমেন্টের সম্পূর্ণ কাঠামো—প্রতিটি সাবমডিউল এবং তার ৩টি ধাপ খুলে দেখুন।',btn('Download blueprint','download-blueprint','','download'))+`<div class="stats">${stat('Modules',16,'Business areas','grid')}${stat('Submodules',64,'Individual demo workspaces','folder')}${stat('Workflow phases',192,'Prepare → Review → Result','connect')}${stat('Source mapping','100%','All requirement IDs linked','shield')}</div><div class="filters"><input id="coverage-search" aria-label="Filter modules" placeholder="Search module, submodule or requirement…"></div><div class="panel" id="coverage-list">${coverageRows('')}</div>`;}
function coverageRows(q){return modules.filter(m=>(m.id+m.title+titles[modules.indexOf(m)]+m.subs.map(s=>s.title).join(' ')).toLowerCase().includes(q.toLowerCase())).map(m=>`<div class="coverage-row"><div class="coverage-head"><span class="tile-icon green">${icon(icons[modules.indexOf(m)])}</span><div><small>${m.id}</small><h3>${titles[modules.indexOf(m)]}</h3><small>${m.title}</small></div></div><div>${m.subs.map(s=>`<div style="margin-bottom:12px"><a href="#/module/${m.id}/${s.id.split('.')[1]}" class="link">${s.id} · ${s.title}</a><div class="coverage-links" style="margin-top:7px">${s.phases.map((p,i)=>`<a href="#/module/${m.id}/${s.id.split('.')[1]}/${i+1}">${p.id} · ${phaseNames[i]}</a>`).join('')}</div></div>`).join('')}</div></div>`).join('')||'<div class="empty">No matching module. Try a different search.</div>';}
function modulePage(m){const i=modules.indexOf(m);const sub=m.subs.find(s=>s.id===`${m.id}.${route[2]}`);if(route[2]&&!sub)return head('Submodule not found','Module explorer থেকে সঠিক কাজটি নির্বাচন করুন।',link('Open module',`module/${m.id}`,'primary'));return head(sub?sub.title:titles[i],sub?`${sub.id} · ${m.title}`:m.title,sub?link('Module overview',`module/${m.id}`,'','grid'):link('View blueprint','coverage','','book'))+`<nav class="subnav" aria-label="Submodules">${m.subs.map(s=>`<a class="${s===sub?'active':''}" href="#/module/${m.id}/${s.id.split('.')[1]}"><small>${s.id}</small>${s.title}</a>`).join('')}</nav>`+(sub?flowPage(m,sub):moduleLanding(m));}
function moduleLanding(m){const i=modules.indexOf(m);return `<div class="context-note">${icon('compass')} উপরের সাবমডিউল থেকে একটি কাজ বাছুন। প্রতিটিতে ইনপুট, যাচাই ও ফলাফলের আলাদা demo workspace আছে।</div>`+({M02:imports,M05:companies,M08:contentStudio,M09:creativeStudio,M10:videoStudio,M11:approvals,M12:campaignView,M13:inboxView,M14:leadView,M15:erpView,M16:settingsView}[m.id]?.()||genericModule(m))+`<div class="section-title"><h2>All workflows in this module</h2><span class="meta">4 submodules · 12 phases</span></div><div class="grid-equal">${m.subs.map((s,j)=>`<a class="module-card" href="#/module/${m.id}/S${j+1}"><div class="flex-between"><span class="pill">${s.id}</span>${icon('arrow')}</div><h3>${s.title}</h3><p>${workItems[i][j][0]}</p><div class="pill-list" style="margin-top:15px">${s.phases.map((p,k)=>`<span class="pill">${p.id} ${phaseNames[k]}</span>`).join('')}</div></a>`).join('')}</div>`;}
function genericModule(m){const i=modules.indexOf(m);return `<div class="grid-2">${panel('Current work queue',`<div class="panel-body">${m.subs.map((s,j)=>`<a class="review-row" href="#/module/${m.id}/S${j+1}"><span class="tile-icon green">${icon(icons[i])}</span><span class="grow"><strong>${workItems[i][j][0]}</strong><small>${s.title}</small></span>${pill(j===0?'Ready':'Draft')}${icon('chevron')}</a>`).join('')}</div>`)}${panel('Workspace context',`<div class="panel-body"><span class="pill green">Demo context</span><h2 style="margin:15px 0">Recycled hangtag campaign</h2><p class="muted" style="font-size:14px">Garment buyers · Gazipur & Dhaka<br>Product: 350 GSM recycled hangtag<br>Goal: qualified sample inquiries</p><div class="detail-list"><div class="detail-row"><span>Company</span><b>Meghna Apparel Studio</b></div><div class="detail-row"><span>Contact</span><b>Nadia Rahman</b></div><div class="detail-row"><span>Purpose</span><b>Sample catalogue request</b></div></div><div style="margin-top:20px">${link('Start first workflow',`module/${m.id}/S1`,'primary','arrow')}</div></div>`)}</div>`;}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>companyModal(b.dataset.company));$('#coverage-search')?.addEventListener('input',e=>{$('#coverage-list').innerHTML=coverageRows(e.target.value);});bindModule();}
function action(a){if(a==='menu')$('#sidebar').classList.toggle('open');else if(a==='search')searchModal();else if(a==='notifications')modal('Your attention queue',`<div class="review-row">${icon('image')}<a class="link" href="#/module/M11">Review campaign creatives</a></div><div class="review-row">${icon('inbox')}<a class="link" href="#/module/M13">Review 3 demo inquiries</a></div><div class="review-row">${icon('shield')}<a class="link" href="#/module/M04">Resolve data quality exceptions</a></div>`);else if(a==='reset')modal('Reset this demo?',`<p>এই browser session-এর পরিবর্তন মুছে প্রাথমিক কাল্পনিক ডেটা ফিরিয়ে আনা হবে।</p><div class="actions" style="margin-top:20px">${btn('Reset demo data','confirm-reset','danger')}${btn('Keep my changes','close')}</div>`);else if(a==='confirm-reset'){state=initial();importRows=null;save();$('#modal').close();render();toast('Demo reset.');}else if(a==='close')$('#modal').close();else if(a==='download-blueprint')download('gm-print-blueprint.json',JSON.stringify(modules,null,2),'application/json');else moduleAction(a);}
function modal(title,body){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!el.open)el.showModal();el.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));el.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>el.close()));}
function searchModal(){modal('Search the workspace','<input id="global-search" aria-label="Search modules and workflows" placeholder="Try: content, ERP, upload, lead…"><div class="search-results" id="search-results"></div>');const input=$('#global-search');input.oninput=()=>{const q=input.value.toLowerCase();$('#search-results').innerHTML=modules.flatMap((m,i)=>[{label:titles[i],detail:m.title,path:`module/${m.id}`},...m.subs.map(s=>({label:s.title,detail:s.id,path:`module/${m.id}/${s.id.split('.')[1]}`}))]).filter(x=>(x.label+x.detail).toLowerCase().includes(q)).slice(0,15).map(x=>`<a class="search-result" href="#/${x.path}">${x.label}<small>${x.detail}</small></a>`).join('')||'<p class="empty">No results found.</p>';$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#modal').close());};input.oninput();input.focus();}
function download(name,data,type='text/plain'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function companyModal(id){const c=state.companies.find(x=>x.id===id);modal(esc(c.name),`<div class="flex-between"><span class="pill">${c.id}</span>${pill(c.status)}</div><div class="detail-list">${Object.entries({Industry:c.industry,Location:c.location,Contact:c.contact,Role:c.role,Email:c.email,Permission:c.consent,Channels:c.channels.join(', '),Source:'Fictional demo fixture',ERP:'Not transferred'}).map(([k,v])=>`<div class="detail-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="context-note" style="margin-top:20px;margin-bottom:0">Demo contact only. No real email or phone number.</div>`);}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchModal();}});
async function init(){try{if(typeof BUNDLED_REQUIREMENTS!=='undefined'){modules=BUNDLED_REQUIREMENTS;}else{const r=await fetch('./requirements.json');if(!r.ok)throw Error('Unable to load module blueprint');modules=await r.json();}render();registerAgentTools();}catch(e){$('#app').innerHTML='<div class="empty"><h1>Workspace could not load</h1><p>Please reload or check your connection.</p><button class="btn" onclick="location.reload()">Retry</button></div>';console.error(e);}}
function registerAgentTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;try{Promise.resolve(ctx.registerTool({name:'read_demo_workspace',title:'Read demo workspace',description:'Read counts from the visible fictional marketing workspace.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({companies:state.companies.length,qualifiedLeads:state.qualified.length,erpAccepted:state.transfers.filter(x=>x.status==='Accepted').length,modules:modules.length,mode:'demo'})})).catch(()=>{});Promise.resolve(ctx.registerTool({name:'navigate_demo_workflow',title:'Open demo workflow',description:'Navigate to a module and optionally a submodule phase. Does not complete or modify a workflow.',inputSchema:{type:'object',properties:{module:{type:'string'},submodule:{type:'integer',minimum:1,maximum:4},phase:{type:'integer',minimum:1,maximum:3}},required:['module'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!modules.some(m=>m.id===input.module)||input.submodule!==undefined&&(!Number.isInteger(input.submodule)||input.submodule<1||input.submodule>4)||input.phase!==undefined&&(!Number.isInteger(input.phase)||input.phase<1||input.phase>3||!input.submodule))throw Error('Invalid workflow route');const path=`/module/${input.module}${input.submodule?'/S'+input.submodule:''}${input.phase?'/'+input.phase:''}`;location.hash=path;render();return{route:path,mode:'demo',completed:false};}})).catch(()=>{});}catch{}}
function flowContext(){const m=currentModule(),s=m?.subs.find(x=>x.id===`${m.id}.${route[2]}`);if(!s)return null;const i=modules.indexOf(m),j=m.subs.indexOf(s);return{m,s,i,j,item:workItems[i][j],phase:Math.min(3,Math.max(1,Number(route[3])||1)),flow:state.flows[s.id]||{prepared:false,reviewed:false,complete:false}};}
function flowPage(m,s){const c=flowContext(),{item,phase,flow}=c;const values=state.forms[s.id]||item[1].map(x=>x.split('|').slice(1).join('|'));let body='';
if(phase===1)body=`<form id="workflow-form"><div class="form-grid">${item[1].map((f,i)=>`<label class="field">${esc(f.split('|')[0])}<input name="field${i}" required maxlength="1000" value="${esc(values[i])}" data-flow-field="${i}"></label>`).join('')}</div><div class="helper" style="margin-top:16px">ডেমো তথ্য পরিবর্তন করে নিজের workflow ধারণা পরীক্ষা করতে পারেন।</div><div id="flow-error" class="error" role="alert"></div><div class="flow-actions"><span class="state-label">${flow.prepared?'Draft saved in this browser':'Ready to prepare'}</span><button class="btn primary" type="submit">Save & continue ${icon('arrow')}</button></div></form>`;
if(phase===2)body=`<div class="detail-list">${item[1].map((f,i)=>`<div class="detail-row"><span>${esc(f.split('|')[0])}</span><b>${esc(values[i])}</b></div>`).join('')}</div><div class="context-note" style="margin-top:20px">${esc(s.phases[1].text)}</div><label class="check-row"><input type="checkbox" id="review-confirm" ${flow.reviewed?'checked':''}>তথ্য, প্রয়োজনীয় অনুমতি ও ফলাফলের সীমা পরীক্ষা করেছি।</label><div id="flow-error" class="error" role="alert"></div><div class="flow-actions">${link('Back to inputs',`module/${m.id}/${route[2]}/1`,'')}${btn('Run demo process','process-flow','primary','spark')}</div>`;
if(phase===3)body=flow.reviewed?`<span class="pill green">Demo process completed</span><div class="result-block generated" style="margin-top:16px">${esc(item[2])}</div><div class="detail-list" style="margin-top:18px"><div class="detail-row"><span>Work item</span><b>${esc(item[0])}</b></div><div class="detail-row"><span>Record</span><b>${s.id}-DEMO</b></div><div class="detail-row"><span>State</span><b>${flow.complete?'Saved to demo activity':'Ready for handoff'}</b></div></div><div class="helper">ফলাফল একটি পূর্বনির্ধারিত demo example। পরিবর্তিত ইনপুট নিচের review/export-এ থাকে; এখানে live AI processing নয়।</div><div class="flow-actions">${btn('Export result','export-flow','','download')}${btn(flow.complete?'Saved ✓':'Save result','complete-flow','primary','check')}</div>`:`<div class="empty">${icon('clock')}<h3>Review this work item first</h3><p>ইনপুট যাচাই এবং demo process শেষ হলে এখানে ফলাফল দেখবেন।</p><div style="margin-top:20px">${link('Go to review',`module/${m.id}/${route[2]}/2`,'primary')}</div></div>`;
return `<div class="stepper" role="navigation" aria-label="Workflow phases">${s.phases.map((p,k)=>`<a class="phase ${phase===k+1?'active':''} ${(k===0&&flow.prepared)||(k===1&&flow.reviewed)||(k===2&&flow.complete)?'done':''}" href="#/module/${m.id}/${route[2]}/${k+1}" ${phase===k+1?'aria-current="step"':''}><span class="phase-no">${k+1}</span><span><b>${phaseNames[k]}</b><small>${p.id} · ${['ইনপুট ও প্রস্তুতি','যাচাই ও প্রক্রিয়া','ফলাফল ও হস্তান্তর'][k]}</small></span></a>`).join('')}</div><div class="grid-2">${panel(item[0],`<div class="panel-body">${body}</div>`,pill(`Phase ${phase} / 3`))}${panel('What this phase handles',`<div class="panel-body"><span class="pill blue">${s.id}.${s.phases[phase-1].id}</span><p class="bn" style="margin-top:17px">${esc(s.phases[phase-1].text)}</p><div class="section-title"><h3>Full workflow</h3></div>${s.phases.map((p,k)=>`<div class="audit"><b>${p.id} · ${phaseNames[k]}</b><p class="muted" style="font-size:12px;margin-top:6px">${esc(p.text)}</p></div>`).join('')}<div style="margin-top:20px">${link('Browse all requirements','coverage','small ghost','book')}</div></div>`)}</div>`;}
function imports(){return `<div class="grid-2">${panel('Bring your own company data',`<div class="panel-body"><div class="dropzone">${icon('upload')}<h3>Upload a company list</h3><p>CSV works locally in this demo. Excel, PDF, card OCR and ERP imports have dedicated workflow previews.</p><div class="actions">${btn('Load sample CSV','sample-import','primary','upload')}<label class="btn" for="csv-file">Choose CSV</label><input type="file" id="csv-file" accept=".csv,text/csv" hidden></div><p style="margin-top:14px;font-size:11px">Demo files only · max 1 MB · nothing uploaded to a server</p></div><div id="import-preview" class="file-preview">${importPreview()}</div></div>`,btn('CSV template','template','small','download'))}${panel('Import with confidence',`<div class="panel-body"><div class="review-row"><span class="tile-icon green">1</span><span class="grow"><strong>Map your columns</strong><small>company · email · industry · location</small></span></div><div class="review-row"><span class="tile-icon green">2</span><span class="grow"><strong>Review data quality</strong><small>Duplicates and invalid rows are separated</small></span></div><div class="review-row"><span class="tile-icon green">3</span><span class="grow"><strong>Import valid records</strong><small>Unknown consent stays unknown</small></span></div><div class="context-note" style="margin-top:20px">ডেমোতে নিজের সংবেদনশীল ডেটা না দিয়ে sample file ব্যবহার করুন।</div></div>`)}</div>`;}
function importPreview(){if(!importRows)return '<p class="meta">Required columns: company, email. Optional: industry, location.</p>';const valid=importRows.filter(r=>r.status==='Ready').length;return `<div class="metric-strip"><div><b>${importRows.length}</b><span>Total rows</span></div><div><b>${valid}</b><span>Ready</span></div><div><b>${importRows.filter(r=>r.status==='Duplicate').length}</b><span>Duplicate</span></div><div><b>${importRows.filter(r=>r.status==='Rejected').length}</b><span>Rejected</span></div></div><div class="table-wrap"><table><thead><tr><th>COMPANY</th><th>VALIDATION</th></tr></thead><tbody>${importRows.map(r=>`<tr><td><strong>${esc(r.company||'Missing company')}</strong><small>${esc(r.email)}</small></td><td>${pill(r.status,r.status==='Ready'?'green':r.status==='Rejected'?'red':'orange')}<small>${esc(r.reason||'Ready to import')}</small></td></tr>`).join('')}</tbody></table></div><div class="actions" style="margin-top:18px">${btn(`Import ${valid} valid record${valid===1?'':'s'}`,'commit-import','primary')}${btn('Export validation','export-import','','download')}</div>`;}
function companies(){return `<div class="filters"><input id="company-search" placeholder="Search company, contact or email…" aria-label="Search companies"><select id="company-filter" aria-label="Company status"><option>All statuses</option><option>Verified</option><option>Needs review</option><option>Suppressed</option></select>${link('Add company','module/M02/S3','primary','plus')}</div>${panel('Company directory',`<div id="company-results">${companyTable(state.companies)}</div>`,pill(`${state.companies.length} profiles`),'Click a profile to see people, channels, consent and source')}`;}
function contentStudio(){return `<div class="grid-2">${panel('Write your next campaign',`<div class="panel-body"><form id="copy-form"><div class="form-grid"><label class="field">Product<input name="product" required value="${esc(state.drafts.product||'Recycled hangtag')}"></label><label class="field">Audience<select name="audience"><option>Garment purchase managers</option><option>Retail brand owners</option><option>Textile merchandisers</option></select></label><label class="field">Channel<select name="channel"><option>Email</option><option>WhatsApp</option><option>Facebook</option><option>LinkedIn</option></select></label><label class="field">Language<select name="language"><option>বাংলা</option><option>English</option></select></label><label class="field wide">Creative direction<textarea name="brief">${esc(state.drafts.brief||'Introduce our sample catalogue. Focus on product detail, quality and the next step. No price or certification claims.')}</textarea></label></div><div class="flow-actions"><span class="meta">AI simulation · no API calls</span><button class="btn primary" type="submit">${icon('spark')} Generate demo copy</button></div></form></div>`)}${panel('Copy preview',`<div class="panel-body">${state.drafts.copy?`<span class="pill purple">Draft · needs approval</span><div class="result-block" style="margin-top:16px">${esc(state.drafts.copy)}</div><div class="actions" style="margin-top:20px">${btn('Send to review','copy-review','primary','check')}${btn('Download copy','copy-export','','download')}</div>`:`<div class="empty">${icon('edit')}<h3>Your draft starts here</h3><p>পণ্য ও নির্দেশনা দিন, তারপর demo copy তৈরি করুন।</p></div>`}</div>`)}</div>`;}
function creativeCards(review=false){return `<div class="card-grid">${creativeNames.map((n,i)=>`<article class="creative"><div class="creative-art ${['','orange','blue'][i]}"><small>GM PRINT SOLUTION</small><strong>${['Your brand.<br>In every detail.','Packaging that<br>tells your story.','Small label.<br>Lasting identity.'][i]}</strong><span>${['RECYCLED HANGTAG COLLECTION','PACKAGING & PRINT ESSENTIALS','WOVEN LABEL COLLECTION'][i]}</span></div><div class="creative-info"><div class="flex-between"><span class="meta">${['EMAIL / SOCIAL','SOCIAL CAROUSEL','SHORT VIDEO CONCEPT'][i]}</span>${pill(state.approved[i]?'Approved':'Draft')}</div><h3 style="margin-top:10px">${n}</h3><p class="meta">Original typographic concept · demo v1</p><div class="actions">${btn('Preview',`preview-creative-${i}`,'small')}${review?btn(state.approved[i]?'Approved ✓':'Approve',`approve-${i}`,'small primary','check'):link('Open design workflow',`module/M09/S${i+1}`,'small','arrow')}</div></div></article>`).join('')}</div>`;}
function creativeStudio(){return `<div class="context-note">Typography-led demo creatives. Image generation, mockups and bulk variations can be explored in the four workflows above.</div>${creativeCards()}`;}
function videoStudio(){return `<div class="grid-2">${panel('Product story · 15 seconds',`<div class="panel-body"><div class="creative-art blue" style="height:230px;border-radius:8px"><small>STORYBOARD PREVIEW · NOT A RENDERED VIDEO</small><strong>Made for your<br>next collection.</strong><span>WOVEN LABELS · SAMPLE CATALOGUE</span></div><div class="actions" style="margin-top:18px">${btn('Preview storyboard','storyboard','primary','video')}${link('Voice & subtitles','module/M10/S3','','edit')}</div></div>`)}${panel('Scene timeline',`<div class="panel-body">${[['00–04s','Material','Introduce fabric and texture'],['04–10s','Detail','Show approved print details'],['10–15s','Next step','Invite a sample catalogue request']].map(x=>`<div class="review-row"><span class="pill blue">${x[0]}</span><span class="grow"><strong>${x[1]}</strong><small>${x[2]}</small></span></div>`).join('')}<p class="meta" style="margin-top:22px">Script, editing, voice, subtitles and interactive lead content have individual workflow demos.</p></div>`)}</div>`;}
function approvals(){return `<div class="section-title" style="margin-top:0"><h2>Creative review queue</h2><span class="pill orange">${3-state.approved.filter(Boolean).length} awaiting review</span></div>${creativeCards(true)}${state.drafts.review?`<div class="section-space">${panel('Generated copy · review',`<div class="panel-body"><div class="result-block">${esc(state.drafts.copy)}</div><div class="actions" style="margin-top:18px">${btn(state.drafts.copyApproved?'Copy approved ✓':'Approve copy','approve-copy','primary','check')}</div></div>`)}</div>`:''}`;}
function campaignView(){return `${panel('Campaign workspace',`<div class="table-wrap"><table><thead><tr><th>CAMPAIGN</th><th>CHANNEL</th><th>DEMO SPEND</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${state.campaigns.map((c,i)=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.segment)}</small></td><td>${esc(c.channel)}</td><td>${money(c.spend)}<small>Cap ${money(c.budget)}</small></td><td>${pill(c.status)}</td><td>${btn(c.status==='Running'?'Pause':c.status==='Paused'?'Resume':'Launch demo',`campaign-${i}`,'small')}</td></tr>`).join('')}</tbody></table></div>`,link('New campaign draft','module/M12/S3','small primary','plus'),'No real spend or publishing · asset approval is required')}<div class="section-title"><h2>Channel capabilities</h2><span class="meta">Demo connections</span></div><div class="module-grid">${[['Email','Send · receive · measure','Demo ready'],['WhatsApp','Template · reply · capture','Opt-in required'],['Facebook','Publish · advertise · capture','Demo ready'],['LinkedIn','Content · approved API','Limited / manual']].map(([a,b,c])=>`<a href="#/module/M12/S1" class="module-card"><div class="flex-between"><span class="tile-icon green">${icon('connect')}</span>${pill(c,c==='Demo ready'?'green':'orange')}</div><h3>${a}</h3><p>${b}</p></a>`).join('')}</div>`;}
function inboxView(){const m=messages[state.selectedMessage];return panel('All conversations',`<div class="inbox"><div class="message-list">${messages.map((m,i)=>`<button class="message-item ${i===state.selectedMessage?'active':''}" data-action="message-${i}"><div class="flex-between"><strong style="font-size:13px">${m.name}</strong><span class="pill">${m.channel}</span></div><p>${m.subject}</p><small>${m.company}</small></button>`).join('')}</div><div class="message-detail"><div class="flex-between"><div><h2>${m.name}</h2><small>${m.company} · ${m.channel}</small></div>${pill(m.status)}</div><div class="message-bubble">${m.body}</div><div class="ai-note"><strong>${icon('spark')} AI classification · demo</strong><div class="detail-row"><span>Intent</span><b>${m.intent}</b></div><div class="detail-row"><span>Product</span><b>${m.product}</b></div><div class="detail-row"><span>Quantity / timeline</span><b>${m.quantity} / ${m.timeline}</b></div><div class="detail-row"><span>Fit score</span><b>${m.fit} / 100 · illustrative</b></div></div><div class="actions" style="margin-top:20px">${m.status==='Qualified'?btn(state.qualified.includes(m.id)?'Lead created ✓':'Create qualified lead','qualify','primary','target'):m.status==='Needs review'?btn('Prepare follow-up','followup','primary','edit'):btn('Archive as irrelevant','archive-message','','check')}${link('Open qualification','module/M14','','arrow')}</div></div></div>`,pill('3 demo inquiries'));}
function leadView(){const qualified=messages.filter(m=>state.qualified.includes(m.id));return `<div class="stats">${stat('Qualified',qualified.length,'Ready for ERP handoff','target')}${stat('Needs review',1,'Missing quantity and timeline','clock')}${stat('Irrelevant',1,'Job application excluded','shield')}${stat('Accepted by ERP',state.transfers.filter(t=>t.status==='Accepted').length,'Acknowledgement received · demo','connect')}</div>${panel('Lead review queue',qualified.length?`<div class="table-wrap"><table><thead><tr><th>COMPANY</th><th>REQUIREMENT</th><th>CONFIDENCE</th><th>ACTION</th></tr></thead><tbody>${qualified.map(m=>`<tr><td><strong>${m.company}</strong><small>LD-${m.id} · ${m.name}</small></td><td>${m.product}<small>${m.quantity} · ${m.timeline}</small></td><td>${pill('High','green')}</td><td>${btn('Send to ERP demo',`transfer-${m.id}`,'small primary','connect')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('target')}<h3>Start with a real buying signal</h3><p>ডেমো inbox-এর sample request যাচাই করে qualified lead তৈরি করুন।</p><div style="margin-top:20px">${link('Open response inbox','module/M13','primary','inbox')}</div></div>`,link('ERP handoff queue','module/M15','small','arrow'))}`;}
function erpView(){return `<div class="context-note">Sales assignment, quotations, orders and KPI belong to your existing ERP. This screen previews the integration boundary.</div><div class="grid-2">${panel('Transfer queue',state.transfers.length?`<div class="table-wrap"><table><thead><tr><th>LEAD</th><th>ERP REFERENCE</th><th>STATUS</th><th></th></tr></thead><tbody>${state.transfers.map(t=>`<tr><td><strong>${t.lead}</strong><small>Same key on retry</small></td><td>${t.status==='Accepted'?t.ref:'—'}</td><td>${pill(t.status)}</td><td>${btn('Retry safely',`retry-${t.lead}`,'small')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('connect')}<h3>No transfer yet</h3><p>Qualified lead তৈরি করে ERP demo-তে পাঠান।</p>${link('View leads','module/M14','primary')}</div>`,pill('Sandbox','blue'))}${panel('Data contract',`<div class="panel-body"><div class="codebox">${esc(JSON.stringify({schema:'v1',company_id:'CMP-001',lead_id:'LD-MSG-001',product:'Recycled hangtag',quantity:10000,consent:'demo_opt_in',source:'WhatsApp',idempotency_key:'gm-MSG-001-v1'},null,2))}</div><div class="actions" style="margin-top:18px">${link('Review mapping','module/M15/S1','','connect')}${btn('Simulate timeout','timeout','small')}</div><p class="helper">Retry uses the same key and returns the same demo ERP reference.</p></div>`)}</div>`;}
function settingsView(){return `<div class="grid-2">${panel('Workspace controls',`<div class="panel-body">${[['mask','Mask sensitive inputs','Remove confidential details before AI processing.'],['review','Human review required','Keep generated content in review before publishing.'],['consent','Consent gate','Protect direct campaigns from unknown or opted-out contacts.']].map(([k,t,d])=>`<div class="switch-row"><div><h3>${t}</h3><p>${d}</p></div><button class="switch" role="switch" aria-checked="${state.settings[k]}" aria-label="${t}" data-action="setting-${k}"></button></div>`).join('')}<div class="switch-row"><div><h3>Emergency pause</h3><p>Stop all demo campaign launches and ERP transfers.</p></div><button class="switch" role="switch" aria-checked="${state.paused}" aria-label="Emergency pause" data-action="pause-all"></button></div><p class="helper">Demo controls illustrate policy. No live security or authentication is configured.</p></div>`)}${panel('Activity history',`<div class="panel-body">${state.audit.length?state.audit.slice(0,8).map(a=>`<div class="audit"><span class="pill">${esc(a.time)}</span> ${esc(a.action)}</div>`).join(''):'<div class="empty">Your demo actions will appear here.</div>'}</div>`,btn('Export log','export-audit','small','download'))}</div>`;}
function parseCSV(text){const rows=[];let row=[],v='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){v+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(v.trim());v='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v.trim());if(row.some(Boolean))rows.push(row);row=[];v='';}else v+=c;}if(quote)throw Error('Unclosed quote in CSV.');row.push(v.trim());if(row.some(Boolean))rows.push(row);if(!rows.length)throw Error('CSV is empty.');const headers=rows.shift().map(x=>x.replace(/^\uFEFF/,'').toLowerCase());if(!headers.includes('company')||!headers.includes('email'))throw Error('CSV must contain company and email columns.');const seen=new Set(state.companies.map(c=>c.email.toLowerCase()));return rows.map(r=>{const o=Object.fromEntries(headers.map((h,i)=>[h,r[i]||'']));let status='Ready',reason='';if(!o.company||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(o.email)){status='Rejected';reason='Company name or valid email missing';}else if(seen.has(o.email.toLowerCase())){status='Duplicate';reason='Email already exists in directory or batch';}else seen.add(o.email.toLowerCase());return{...o,status,reason};});}
function bindModule(){const form=$('#workflow-form');if(form){form.onsubmit=e=>{e.preventDefault();const c=flowContext(),values=[...form.querySelectorAll('input')].map(x=>x.value.trim());if(values.some(x=>!x)){$('#flow-error').textContent='সব field পূরণ করুন।';return;}state.forms[c.s.id]=values;state.flows[c.s.id]={prepared:true,reviewed:false,complete:false};log(`Prepared ${c.s.id}`);location.hash=`/module/${c.m.id}/${route[2]}/2`;};}
const filterCompanies=()=>{const q=$('#company-search').value.toLowerCase(),s=$('#company-filter').value;$('#company-results').innerHTML=companyTable(state.companies.filter(c=>(c.name+c.contact+c.email).toLowerCase().includes(q)&&(s==='All statuses'||c.status===s)));$('#company-results').querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>companyModal(b.dataset.company));};$('#company-search')?.addEventListener('input',filterCompanies);$('#company-filter')?.addEventListener('change',filterCompanies);
$('#csv-file')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024){toast('Choose a CSV under 1 MB.');return;}try{importRows=parseCSV(await f.text());log(`CSV preview: ${importRows.length} rows`);render();}catch(err){toast(err.message);}});
$('#copy-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),product=f.get('product').trim();if(!product)return;const bn=f.get('language')==='বাংলা';state.drafts={product,brief:f.get('brief'),copy:bn?`আপনার ব্র্যান্ডের পরিচয়, প্রতিটি খুঁটিনাটিতে।\n\n${product} নিয়ে নতুন collection-এর পরিকল্পনা করছেন? GM Print Solution-এর sample catalogue দিয়ে শুরু করুন। আপনার material, size ও design requirement জানান।\n\nস্যাম্পল ক্যাটালগ পেতে উত্তর দিন।\n\nDemo variant · ${f.get('channel')} · ${f.get('audience')}`:`Your brand, in every detail.\n\nPlanning your next collection with ${product}? Explore the GM Print Solution sample catalogue. Tell us your material, size and design requirements.\n\nReply to request your sample catalogue.\n\nDemo variant · ${f.get('channel')} · ${f.get('audience')}`,review:false,copyApproved:false};log('Generated demo copy');render();toast('Demo copy generated. Review before use.');});}
function moduleAction(a){
if(a==='process-flow'){const c=flowContext();if(!$('#review-confirm')?.checked){$('#flow-error').textContent='প্রথমে review confirmation নির্বাচন করুন।';return;}state.flows[c.s.id]={...c.flow,prepared:true,reviewed:true,complete:false};if(!state.forms[c.s.id])state.forms[c.s.id]=c.item[1].map(x=>x.split('|').slice(1).join('|'));log(`Processed ${c.s.id} · simulation`);location.hash=`/module/${c.m.id}/${route[2]}/3`;}
else if(a==='complete-flow'){const c=flowContext();if(!c.flow.reviewed)return;state.flows[c.s.id]={...c.flow,complete:true};log(`Saved result ${c.s.id}`);render();toast('Result saved to demo activity.');}
else if(a==='export-flow'){const c=flowContext();download(`${c.s.id}-demo.json`,JSON.stringify({requirement:c.s.id,input:state.forms[c.s.id],result:c.item[2],mode:'simulation'},null,2),'application/json');}
else if(a==='sample-import'){importRows=parseCSV('company,email,industry,location\nHarbor Garment Works,rumi@harbor-garment.example,Garments,Dhaka\nMeghna Apparel Studio,nadia@meghna-apparel.example,Garments,Gazipur\nBroken Row,invalid-email,Textile,Dhaka');render();}
else if(a==='template')download('company-template.csv','company,email,industry,location\nHarbor Garment Works,rumi@harbor-garment.example,Garments,Dhaka','text/csv');
else if(a==='export-import')download('validation-report.json',JSON.stringify(importRows,null,2),'application/json');
else if(a==='commit-import'){const ready=importRows?.filter(r=>r.status==='Ready'&&!state.companies.some(c=>c.email.toLowerCase()===r.email.toLowerCase()))||[];if(!ready.length){toast('No new valid records to import.');return;}ready.forEach(r=>state.companies.push({id:`CMP-${String(state.companies.length+1).padStart(3,'0')}`,name:r.company,email:r.email,industry:r.industry||'Unknown',location:r.location||'Unknown',contact:'Not provided',role:'Unknown',channels:['Email'],consent:'Unknown',status:'Needs review',score:0}));importRows=importRows.map(r=>r.status==='Ready'?{...r,status:'Imported'}:r);log(`Imported ${ready.length} company records`);render();toast(`${ready.length} record imported. Consent remains unknown.`);}
else if(a==='copy-review'){state.drafts.review=true;log('Copy sent for approval');location.hash='/module/M11';}
else if(a==='copy-export')download('campaign-copy.txt',state.drafts.copy);
else if(a==='approve-copy'){state.drafts.copyApproved=true;log('Campaign copy approved');render();toast('Copy approved in demo.');}
else if(a.startsWith('preview-creative-')){const i=Number(a.split('-').pop());modal(creativeNames[i],`<div class="creative-art ${['','orange','blue'][i]}" style="height:270px;border-radius:9px"><small>GM PRINT SOLUTION</small><strong>${creativeNames[i]}</strong><span>TYPOGRAPHIC DEMO CONCEPT · v1</span></div><div class="detail-row"><span>Usage</span><b>Illustrative design direction</b></div><div class="detail-row"><span>Claims</span><b>No unverified certification</b></div><div class="detail-row"><span>State</span><b>${state.approved[i]?'Approved':'Needs review'}</b></div>`);}
else if(a.startsWith('approve-')){const i=Number(a.split('-')[1]);if(!Number.isInteger(i)||i>2)return;state.approved[i]=true;log(`Approved creative ${i+1}`);render();toast('Creative approved. Campaign can use this version.');}
else if(a==='storyboard')modal('Storyboard · 15 seconds',`<div class="result-block">Scene 1 · 00–04s\nMaterial close-up. Introduce the collection.\n\nScene 2 · 04–10s\nShow approved print details and brand identity.\n\nScene 3 · 10–15s\nCall to action: Request your sample catalogue.</div><p class="helper">This is a storyboard demo, not a generated video file.</p>`);
else if(a.startsWith('campaign-')){const i=Number(a.split('-')[1]),c=state.campaigns[i];if(state.paused){toast('Emergency pause is active. Resume in Administration.');return;}if(c.status==='Running'){c.status='Paused';}else if(!state.approved[i]){toast('Approve the matching creative in Assets & approvals first.');return;}else c.status='Running';log(`Campaign ${i+1}: ${c.status} · no live spend`);render();toast(`Demo campaign ${c.status.toLowerCase()}.`);}
else if(a.startsWith('message-')){state.selectedMessage=Number(a.split('-')[1]);save();render();}
else if(a==='qualify'){const m=messages[state.selectedMessage];if(m.status!=='Qualified')return;if(!state.qualified.includes(m.id))state.qualified.push(m.id);log(`Qualified ${m.id}`);render();toast('Qualified lead created. Ready for ERP handoff.');}
else if(a==='followup')modal('Qualification follow-up draft',`<div class="result-block">ক্যাটালগের অনুরোধের জন্য ধন্যবাদ। আপনার প্রয়োজনীয় label-এর পরিমাণ এবং সম্ভাব্য delivery সময় জানালে সঠিক sample option সাজেস্ট করতে পারব।</div><p class="helper">Draft only. No email is sent.</p>${link('Review follow-up workflow','module/M14/S3','primary')}`);
else if(a==='archive-message'){log('Job application excluded from marketing leads');toast('Marked irrelevant to sales. No lead created.');}
else if(a.startsWith('transfer-')){transfer(a.slice(9));}
else if(a.startsWith('retry-')){transfer(a.slice(6));}
else if(a==='timeout'){if(!state.transfers.length){toast('Transfer a qualified lead first.');return;}state.transfers[0].status='Failed';log('Simulated ERP timeout');render();toast('Demo timeout simulated. Retry safely to recover.');}
else if(a==='pause-all'){state.paused=!state.paused;if(state.paused)state.campaigns.forEach(c=>{if(c.status==='Running')c.status='Paused';});log(`Emergency pause ${state.paused?'enabled':'disabled'}`);render();}
else if(a.startsWith('setting-')){const key=a.slice(8);if(key==='consent'||key==='review'){toast('This demo keeps consent and human review required.');return;}state.settings[key]=!state.settings[key];log(`${key} setting changed`);render();}
else if(a==='export-audit')download('demo-activity.json',JSON.stringify(state.audit,null,2),'application/json');
}
function transfer(id){if(state.paused){toast('Emergency pause is active.');return;}if(!state.qualified.includes(id)){toast('Lead must be qualified before transfer.');return;}let t=state.transfers.find(x=>x.lead===id);if(t)t.status='Accepted';else{t={lead:id,ref:`ERP-DEMO-${1042+state.transfers.length}`,status:'Accepted',key:`gm-${id}-v1`};state.transfers.push(t);}log(`ERP acknowledged ${id} → ${t.ref}`);if(route[1]==='M15')render();else location.hash='/module/M15';toast('Demo ERP accepted the lead. Same key is safe to retry.');}
init();
